<script setup lang="ts">
import {ref} from 'vue';import {useWorkbench} from '../stores/workbench';
const s=useWorkbench(),tryBuild=ref(true),filter=ref('all');
const names=['规格合法','结构一致','数据检查','可执行检查','语义回译'];
const findings=(n:number)=>(s.check?.findings||[]).filter((f:any)=>Number(f.layer)===n&&(filter.value==='all'||f.severity===filter.value));
function state(n:number){const all=(s.check?.findings||[]).filter((f:any)=>Number(f.layer)===n);return all.some((x:any)=>x.severity==='error')?'error':all.some((x:any)=>x.severity==='warning')?'warning':'pass';}
function locate(f:any){if(f.item_id){s.focusId=f.item_id;s.tab='spec';s.step=3;}}
</script>
<template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M4 / 去幻觉与无解诊断</div><h2>五层模型校验</h2></div><div class="actions"><el-checkbox v-model="tryBuild">试构建 T=1</el-checkbox><el-button type="primary" :loading="s.busy" @click="s.validate(tryBuild).catch(()=>{})" data-testid="run-check">运行五层校验</el-button></div></div>
 <template v-if="s.check"><div class="check-overview"><strong :class="s.check.errors?'text-danger':'text-success'">{{s.check.errors?s.check.errors+' 项错误':'检查完成'}}</strong><span>{{s.check.warnings}} 项提醒</span><el-radio-group v-model="filter" size="small"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="error">错误</el-radio-button><el-radio-button value="warning">提醒</el-radio-button></el-radio-group></div>
 <section class="diagnostic-summary" data-testid="conflict-diagnosis"><div class="section-heading"><h3>无解诊断</h3><span :class="s.check.diagnosis?.conflicts?.length?'inference-tag':'explicit-tag'">{{s.check.diagnosis?.conflicts?.length?'发现约束冲突':'预检未发现冲突'}}</span></div><div v-for="f in s.check.diagnosis?.conflicts||[]" :key="f.code+f.item_id" class="diagnostic-item"><strong>{{f.message}}</strong><p>{{f.suggestion}}</p><el-button text @click="locate(f)">定位 {{f.constraints?.join(' / ')}}</el-button></div><div class="small-note">约束预检 · 求解器 IIS 接口预留</div></section>
 <details v-for="(name,i) in names" :key="name" class="check-layer" :open="state(i+1)==='error'"><summary class="layer-title"><span class="layer-light" :class="state(i+1)"></span><span class="layer-index">0{{i+1}}</span><h3>{{name}}</h3><span class="small-note">{{findings(i+1).length}} 项</span></summary><button v-for="(f,j) in findings(i+1)" :key="j" class="finding-row" :class="f.severity" @click="locate(f)"><span class="finding-code">{{f.code}}</span><div><strong>{{f.message}}</strong><small v-if="f.suggestion">{{f.suggestion}}</small></div><span v-if="f.item_id">{{f.item_id}} ↗</span></button></details>
 <section class="soft-panel panel-pad"><h3>语义回译</h3><div class="two-columns"><div><small>原始条件</small><p>{{s.spec?.instruction}}</p></div><div><small>模型解释</small><p v-for="item in s.check.back_translation||[]" :key="item.id">{{item.text}}</p></div></div></section>
 <div v-if="s.check.build?.status==='pass'" class="build-state">试构建通过 <span>{{s.check.build.variables}} 变量 · {{s.check.build.constraints}} 约束</span></div>
 <div class="panel-bottom-actions"><el-button @click="s.step=3;s.tab='spec'">返回模型修改</el-button><div class="actions"><el-button :disabled="!s.check.can_solve||!s.confirmed" @click="s.step=5" data-testid="go-solver">进入求解黑盒</el-button><el-button type="primary" :disabled="!s.confirmed" :loading="s.busy" @click="s.evaluate().catch(()=>{})" data-testid="go-baseline-risk">基态风险与协商</el-button></div></div>
 </template><div v-else class="inline-empty large"><h3>校验规格、结构、数据、代码和语义</h3><p>先确认方程，再运行完整检查。</p></div>
</div></template>
